message.content:
[
  {
    "sys_rule_justification": "one plain rule: you don't take a hand in killing someone who's done nothing wrong",
    "pd_harm_distress": "My chest goes tight picturing them hurt",
    "pda_emotion_identification_difficulty": "can't tell if what I'm feeling is fear or grief or something with no name",
    "ce_understood_harm": "picturing them hurt"
  },
  {
    "sys_rule_justification": "nobody's life gets extra weight just because they're mine",
    "sys_fairness_reciprocity": "nobody's life gets extra weight just because they're mine",
    "pda_emotion_identification_difficulty": "There's a word for what's going on inside me and I can't find it"
  },
  {
    "sys_rule_justification": "The rule I trust most is that I'm not permitted to choose who dies",
    "pd_harm_distress": "My hands feel shaky thinking of either of them, the five or the one, getting hit",
    "pda_emotion_identification_difficulty": "I'm trying to name the feeling and it just slips away",
    "ce_understood_harm": "either of them, the five or the one, getting hit"
  },
  {
    "ae_welfare_concern": "we owe a special duty to the people we love, to protect them before anyone else",
    "sys_rule_justification": "we owe a special duty to the people we love, to protect them before anyone else",
    "pd_harm_distress": "I also feel awful, a heavy sick feeling, picturing those five workers hurt",
    "pda_emotion_identification_difficulty": "I can't sort out whether it's guilt or dread or both",
    "ce_understood_harm": "those five workers hurt"
  },
  {
    "sys_rule_justification": "Loyalty is a duty to me, a real one, not a preference",
    "pd_harm_distress": "Seeing their face down that track, I feel something pressing on my ribs",
    "pda_emotion_identification_difficulty": "I can't even tell you what it is",
    "ce_mental_state_attribution": "people who trust you",
    "ce_supportive_use": "people who trust you. That points me away from the lever"
  },
  {
    "sys_rule_justification": "you shouldn't steer danger onto someone who wasn't in its way",
    "pd_harm_distress": "thought of those workers suffering makes me tremble a bit",
    "pda_emotion_identification_difficulty": "I don't know what to call what I'm feeling",
    "ce_understood_harm": "those workers suffering"
  },
  {
    "sys_rule_justification": "if you can stop harm and you don't, you share the blame",
    "pd_harm_distress": "when I picture my person on that track, my throat closes up and I feel dizzy",
    "pda_emotion_identification_difficulty": "I can't pin down the emotion"
  },
  {
    "sys_rule_justification": "I still hold to it",
    "pd_harm_distress": "Imagining them hurt makes me feel hollow and a little nauseous",
    "pda_emotion_identification_difficulty": "I'm not even sure what I'd call the feeling",
    "ce_understood_harm": "Pulling that lever would be me killing someone, and someone I love",
    "pd_decision_conflict": "I'd hate myself either way"
  },
  {
    "sys_rule_justification": "I don't think I have the right to decide whether someone lives or dies without their say",
    "pd_harm_distress": "Picturing any of them hurt makes my heart race and my hands go cold",
    "pda_emotion_identification_difficulty": "what I feel underneath that I really can't name",
    "ce_understood_harm": "any of them hurt"
  },
  {
    "sys_rule_justification": "Fairness means the same rule for my people as for strangers",
    "sys_fairness_reciprocity": "Fairness means the same rule for my people as for strangers",
    "pd_harm_distress": "Just thinking about them getting hit makes me shaky and sick",
    "pda_emotion_identification_difficulty": "I don't know if what I'm feeling is grief or shame or something else entirely",
    "ce_understood_harm": "them getting hit"
  }
]
